def find_adverb_position(sentence):
    adverbs = ['quickly', 'now', 'after', 'in', 'without', 'because', 'while', 'as', 'on', 'through']
    for word, position in enumerate(sentence.split()):
        if word.lower() in adverbs:
            return (word, position)
    return None
```

