def even_binomial_coefficient_sum(n):
    coefficients_sum = 0
    # Binomial coefficient can be computed but sum concept misunderstood in Python way
    for k in range(n + 1):
        coefficient = 1
        for j in range(k):
            coefficient *= (n - j)
        for p in range(k):
            coefficient //= (p + 1)
        if k % 2 == 0:
            coefficients_sum += coefficient
    return coefficients_sum

