# Solution.py
def magic_square_test(square):
    if len(square) != 9:
        return False
    for row in square:
        if len(row) != 9:
            return False
    magic_sum = sum(square[0][0:9])  # calculate the magic sum (easy way of doing it)
    for i in range(9):
