def convert_list_to_dict(lst):
    """
    Converts the input list into a nested dictionary.
    """
    def nested_dict_helper(lst):
        if isinstance(lst, list):
            return {str(i): nested_dict_helper(item) for i, item in enumerate(lst)}
        else:
            return lst

    return nested_dict_helper(lst)

def convert_list_dictionary(lst):
    """
    Converts the input list to a nested dictionary.
    """
    if not lst:
        return {}
    if not isinstance(lst[0], list):
        return {lst[0]: convert_list_dictionary(lst[1:])]
    return {key: convert_list_dictionary(val) for key, val in enumerate(lst)}
